    source: "CNBC",
    sourceUrl: "https://www.cnbc.com/2026/11/13/nvidia-huang-ceo-replacement-search.html",
    publishedAt: "2026-11-13T19:33:23+00:00",
    category: "テクノロジー",
    imageUrl: "https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&q=80",
    readTime: 3,
